public boolean shouldPrintMessage(int timestamp, String message) {
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("Timestamp cannot be negative");
    }
    // Assuming a map to store the last printed timestamp for each message
    // This map should be initialized at the class level
    if (lastPrintedTimestamps == null) {
        lastPrintedTimestamps = new HashMap<>();
    }
    Integer lastTimestamp = lastPrintedTimestamps.get(message);
    if (lastTimestamp == null || timestamp - lastTimestamp >= 10) {
        lastPrintedTimestamps.put(message, timestamp);
        return true;
    }
    return false;
}

