ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue == null) {
        enlarge(byteLength);
        for (int i = 0; i < byteLength; i++) {
            data[length++] = 0;
        }
    } else {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset is out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds byteArrayValue length");
        }
        enlarge(byteLength);
        System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
        length += byteLength;
    }
    return this;
}

