private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') {
            // It's a method descriptor, find the argument types
            int endOfParams = descriptor.indexOf(')');
            if (endOfParams == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String paramsPart = descriptor.substring(1, endOfParams);
            while (!paramsPart.isEmpty()) {
                char firstChar = paramsPart.charAt(0);
                switch (firstChar) {
                    case 'B':
                    case 'C':
                    case 'D':
                    case 'F':
                    case 'I':
                    case 'J':
                    case 'S':
                    case 'Z':
                    case 'V':
                        paramsPart = paramsPart.substring(1);
                        break;
                    case 'L':
                        int endOfClass = paramsPart.indexOf(';');
                        if (endOfClass == -1) {
                            throw new IllegalArgumentException("Invalid class descriptor: missing ';'");
                        }
                        paramsPart = paramsPart.substring(endOfClass + 1);
                        break;
                    case '[':
                        int dims = 1;
                        while (paramsPart.charAt(dims) == '[') {
                            dims++;
                        }
                        if ("BCDFIJSZLV".indexOf(paramsPart.charAt(dims)) == -1) {
                            throw new IllegalArgumentException("Invalid array descriptor");
                        }
                        paramsPart = paramsPart.substring(dims + 1);
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown type descriptor: " + firstChar);
                }
            }
        } else {
            // It's a single type descriptor
            switch (descriptor.charAt(0)) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'J':
                case 'S':
                case 'Z':
                case 'V':
                    // Pop one from the stack for these types
                    break;
                case 'L':
                    if (descriptor.charAt(descriptor.length() - 1) != ';') {
                        throw new IllegalArgumentException("Invalid class descriptor: missing ';'");
                    }
                    // Pop one from the stack for class types
                    break;
                case '[':
                    // Pop one from the stack for array types
                    break;
                default:
