    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    double width = box.getWidth();
    double halfWidth = width / 2.0;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(box.getMinX() + halfWidth, box.getMinY(), halfWidth, box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

