private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes must not be null.");
    }

    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    while (!circulator.getNode().equals(stop)) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        circulator.move();
    }

    return circulator; // Return the circulator at the stop node if predicate is not satisfied
}

