boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || vertices.size() < 2) {
        return true; // A single vertex or null set is trivially a clique
    }

    for (V v1 : vertices) {
        if (!graph.containsVertex(v1)) {
            return false; // If any vertex is not in the graph, it's not a valid subgraph
        }
        for (V v2 : vertices) {
            if (v1 != v2 && !graph.containsEdge(v1, v2)) {
                return false; // If any pair of vertices is not connected, it's not a clique
            }
        }
    }
    return true;
}

