private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (i < bb.limit()) {
        byte b1 = bb.get(i++);
        if ((b1 & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b1);
        } else if ((b1 & 0xE0) == 0xC0 && i < bb.limit()) {
            // Two-byte character
            byte b2 = bb.get(i++);
            if ((b2 & 0xC0) == 0x80) {
                sb.append((char) (((b1 & 0x1F) << 6) | (b2 & 0x3F)));
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        } else if ((b1 & 0xF0) == 0xE0 && i < bb.limit() - 1) {
            // Three-byte character
            byte b2 = bb.get(i++);
            byte b3 = bb.get(i++);
            if ((b2 & 0xC0) == 0x80 && (b3 & 0xC0) == 0x80) {
                sb.append((char) (((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 sequence");
            }
        } else if ((b1 & 0xF8) == 0xF0 && i < bb.limit() - 2) {
            // Four-byte character
            byte b2 = bb.get(i++);
            byte b3 = bb.get(i++);
            byte b4 = bb.get(i++);
            if ((b2 & 0xC0) == 0x80 && (b3 & 0xC0) == 0x80 && (b4 & 0xC0) == 0x80) {
