public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Normalize the input paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process the relative path components
    int i = 0;
    while (i < relativePathComponents.length) {
        if (relativePathComponents[i].equals("..")) {
            if (pathComponents.length > 0) {
                // Move up one directory if possible
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else if (!relativePathComponents[i].equals(".")) {
            // Add the component to the path
            String[] newPathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            newPathComponents[pathComponents.length] = relativePathComponents[i];
            pathComponents = newPathComponents;
        }
        i++;
    }

    // Join the path components back into a single string
    return String.join("/", pathComponents);
}

