int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) throw new IllegalArgumentException("OutputStream cannot be null");
    if (message == null) throw new IllegalArgumentException("Message cannot be null");
    if (schema == null) throw new IllegalArgumentException("Schema cannot be null");
    if (buffer == null) throw new IllegalArgumentException("LinkedBuffer cannot be null");

    // Calculate the length of the message
    intSize = schema.getSerializedSize(message, buffer);

    // Ensure the buffer has enough space for the size and the message
    if (buffer.start + intSize + 10 > buffer.buffer.length) {
        buffer = Writter.ensureCapacity(buffer, intSize + 10);
    }

    // Write the length of the message as a varint
    int pos = buffer.start;
    pos = UnsafeUtil.putVarInt32(pos, intSize);
    int lengthVarintSize = pos - buffer.start;

    // Serialize the message into the buffer
    pos = schema.writeTo(buffer, buffer.start + lengthVarintSize, intSize, message);
    int serializedMessageSize = pos - buffer.start - lengthVarintSize;

    // Ensure that the serialized message size matches the calculated size
    if (serializedMessageSize != intSize) {
        throw new IOException("Serialized size does not match expected size. Expected " + intSize + ", but got " + serializedMessageSize);
    }

    // Write the buffer to the OutputStream
    out.write(buffer.buffer, buffer.start, serializedMessageSize + lengthVarintSize);

    // Return the total size of the message including the length varint
    return serializedMessageSize + lengthVarintSize;
}

