    if (data == null || offset < 0 || len < 0 || offset + len > data.length) {
        return false;
    }
    if (this.internalArray == null) {
        return len == 0;
    }
    if (this.internalArray.length != len) {
        return false;
    }
    for (int i = 0; i < len; i++) {
