public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int strLen = str.length();
    int utf8Length = 0;
    for (int i = 0; i < strLen; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            utf8Length++;
        } else if (c < 0x800) {
            utf8Length += 2;
        } else if (Character.isSurrogate(c)) {
            utf8Length += 4;  // Surrogate pair takes 4 bytes in UTF-8
            i++;  // Skip the next character as it is part of the surrogate pair
        } else {
            utf8Length += 3;
        }
    }

    byte[] bytes = new byte[utf8Length];
    int index = 0;
    for (int i = 0; i < strLen; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            bytes[index++] = (byte) c;
        } else if (c < 0x800) {
            bytes[index++] = (byte) (0xC0 | (c >> 6));
            bytes[index++] = (byte) (0x80 | (c & 0x3F));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 >= strLen) {
                throw new IllegalArgumentException("Invalid surrogate pair at the end of string");
            }
            char lowSurrogate = str.charAt(++i);
            int codePoint = Character.toCodePoint(c, lowSurrogate);
            bytes[index++] = (byte) (0xF0 | (codePoint >> 18));
            bytes[index++] = (byte) (0x80 | ((codePoint >> 12) & 0x3F));
            bytes[index++] = (byte) (0x80 | ((codePoint >> 6) & 0x3F));
            bytes[index++] = (byte) (0x80 | (codePoint & 0x3F));
        } else {
            bytes[index++] = (byte) (0xE0 | (c >> 12));
            bytes[index++] = (byte) (0x80 | ((c >> 6) & 0x3F));
            bytes[index++] = (byte) (0x80 | (c & 0x3F));
        }
    }

    return session.writeBytes(lb, bytes, 0, bytes.length);
}

