int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int size = 0;
    try {
        while (node != null) {
            int chunkSize = node.start; // Assuming start holds the size of data in the current chunk
            out.write(node.buffer, 0, chunkSize);
            size += chunkSize;
            node = node.next;
        }
    } catch (IOException e) {
        throw new IOException("Error writing to DataOutput", e);
    }
    return size;
}

